// F-4 (#808 F09, I10): the native inference authority against independent
// reference values (scipy, generated by tools/analysis_inference/
// generate_reference.py into inference_reference.h). No values here are
// produced by the code under test.
#include "backend/analysis/AnalysisInference.h"
#include "analysis/inference_reference.h"
#include "support/assert.h"
#include <cmath>
#include <string>

namespace inf = backend::analysis::inference;
namespace ref = inference_reference;

namespace {
bool near(double actual, double expected, double relative, double absolute = 0) {
    return std::fabs(actual - expected) <= std::max(absolute, relative * std::fabs(expected));
}
#define NEAR(actual, expected, rel, what)                                                       \
    MIB_EXPECT(near((actual), (expected), (rel)),                                              \
               std::string(what) + ": " + std::to_string(actual) + " vs " +                    \
                   std::to_string(expected))
bool hasReason(const std::vector<std::string>& reasons, const std::string& needle) {
    for (const auto& r : reasons)
        if (r.find(needle) != std::string::npos) return true;
    return false;
}
} // namespace

int main() {
    // distributions
    NEAR(inf::studentTCdf(-1.5, 7), ref::tCdf_m1p5_df7, 1e-10, "t cdf");
    NEAR(inf::studentTCdf(2.2, 3.5), ref::tCdf_2p2_df3p5, 1e-10, "t cdf fractional df");
    NEAR(inf::studentTQuantile(0.975, 4), ref::tPpf_0p975_df4, 1e-10, "t quantile");
    NEAR(inf::studentTQuantile(0.995, 27.3), ref::tPpf_0p995_df27p3, 1e-10, "t quantile");
    NEAR(inf::fSurvival(3.1, 4, 20), ref::fSf_3p1_df4_df20, 1e-9, "F survival");
    NEAR(inf::chiSquareSurvival(7.8, 3), ref::chi2Sf_7p8_df3, 1e-9, "chi2 survival");
    NEAR(inf::chiSquareSurvival(40, 10), ref::chi2Sf_40_df10, 1e-9, "chi2 survival far tail");
    NEAR(inf::normalQuantile(0.001), ref::normPpf_0p001, 1e-12, "normal quantile tail");
    NEAR(inf::normalQuantile(0.8), ref::normPpf_0p8, 1e-12, "normal quantile");
    NEAR(inf::regularizedIncompleteBeta(2.5, 4, 0.3), ref::betainc_2p5_4_0p3, 1e-12, "betainc");

    // Welch t on unequal variances (10 vs 20 units)
    const auto welch = inf::welchT(ref::welchReference, ref::welchComparator, 0.95);
    NEAR(welch.statistic, ref::welchT, 1e-10, "Welch t");
    NEAR(*welch.df1, ref::welchDf, 1e-10, "Welch df");
    NEAR(welch.pValue, ref::welchP, 1e-8, "Welch p");
    NEAR(welch.confidenceInterval->lower, ref::welchCiLower, 1e-8, "Welch CI lower");
    NEAR(welch.confidenceInterval->upper, ref::welchCiUpper, 1e-8, "Welch CI upper");

    // Mann-Whitney U with ties (normal approximation, tie + continuity correction)
    const auto ties = inf::mannWhitneyU(ref::mwuTiesReference, ref::mwuTiesComparator);
    NEAR(ties.statistic, ref::mwuTiesU, 1e-12, "MWU U with ties");
    NEAR(ties.pValue, ref::mwuTiesP, 1e-9, "MWU p with ties");
    MIB_EXPECT(ties.pMethod.find("normal approximation") != std::string::npos,
               "tied MWU states the approximation");
    // Mann-Whitney exact (no ties)
    const auto exact = inf::mannWhitneyU(ref::mwuExactReference, ref::mwuExactComparator);
    NEAR(exact.statistic, ref::mwuExactU, 1e-12, "MWU exact U");
    NEAR(exact.pValue, ref::mwuExactP, 1e-10, "MWU exact p");
    MIB_EXPECT(exact.pMethod.find("exact") == 0, "untied small MWU is exact");

    // paired t and Wilcoxon signed-rank
    const auto paired = inf::pairedT(ref::pairedReference, ref::pairedComparator, 0.95);
    NEAR(paired.statistic, ref::pairedT, 1e-10, "paired t");
    NEAR(*paired.df1, ref::pairedDf, 1e-12, "paired df");
    NEAR(paired.pValue, ref::pairedP, 1e-8, "paired p");
    NEAR(paired.confidenceInterval->lower, ref::pairedCiLower, 1e-9, "paired CI lower");
    NEAR(paired.confidenceInterval->upper, ref::pairedCiUpper, 1e-9, "paired CI upper");
    const auto darwin =
        inf::wilcoxonSignedRank(ref::wilcoxonExactReference, ref::wilcoxonExactComparator);
    NEAR(darwin.statistic, ref::wilcoxonExactW, 1e-12, "Wilcoxon exact W (Darwin)");
    NEAR(darwin.pValue, ref::wilcoxonExactP, 1e-12, "Wilcoxon exact p (Darwin)");
    MIB_EXPECT(darwin.pMethod.find("exact") == 0, "untied Wilcoxon is exact");
    const auto tiedPairs =
        inf::wilcoxonSignedRank(ref::wilcoxonTiesReference, ref::wilcoxonTiesComparator);
    NEAR(tiedPairs.statistic, ref::wilcoxonTiesW, 1e-12, "Wilcoxon W with ties and zeros");
    NEAR(tiedPairs.pValue, ref::wilcoxonTiesP, 1e-9, "Wilcoxon p with ties and zeros");
    MIB_EXPECT(!tiedPairs.notes.empty(), "dropped zero differences are reported");

    // one-way ANOVA and Kruskal-Wallis (five groups)
    const auto anova = inf::oneWayAnova(ref::anovaGroups);
    NEAR(anova.statistic, ref::anovaF, 1e-10, "ANOVA F");
    NEAR(anova.pValue, ref::anovaP, 1e-8, "ANOVA p");
    const auto kw = inf::kruskalWallis(ref::anovaGroups);
    NEAR(kw.statistic, ref::kruskalH, 1e-10, "Kruskal-Wallis H");
    NEAR(kw.pValue, ref::kruskalP, 1e-8, "Kruskal-Wallis p");

    // 4PL, log10 scale, unweighted
    inf::LogisticFitRequest request;
    request.concentration = ref::fitConcentration;
    request.response = ref::fitResponse;
    const auto fit = inf::fitLogistic(request);
    MIB_REQUIRE(fit.fitted && fit.converged, "4PL fits");
    NEAR(fit.parameters[0].estimate, ref::fitBottom, 1e-6, "4PL bottom");
    NEAR(fit.parameters[1].estimate, ref::fitTop, 1e-6, "4PL top");
    NEAR(fit.parameters[2].estimate, ref::fitLogEc50, 1e-6, "4PL logEC50");
    NEAR(fit.parameters[3].estimate, ref::fitHill, 1e-6, "4PL hill");
    NEAR(*fit.parameters[0].standardError, ref::fitSeBottom, 1e-5, "4PL SE bottom");
    NEAR(*fit.parameters[1].standardError, ref::fitSeTop, 1e-5, "4PL SE top");
    NEAR(*fit.parameters[2].standardError, ref::fitSeLogEc50, 1e-5, "4PL SE logEC50");
    NEAR(*fit.parameters[3].standardError, ref::fitSeHill, 1e-5, "4PL SE hill");
    NEAR(fit.ec50, ref::fitEc50, 1e-6, "4PL EC50");
    NEAR(fit.ec50Interval->lower, ref::fitEc50Lower, 1e-5, "4PL EC50 CI lower");
    NEAR(fit.ec50Interval->upper, ref::fitEc50Upper, 1e-5, "4PL EC50 CI upper");
    NEAR(fit.rSquared, ref::fitR2, 1e-8, "4PL R squared");
    MIB_EXPECT(std::fabs(fit.ec50 - 3.0) < 0.5, "EC50 recovers the generating 3 nM");
    MIB_EXPECT(fit.suspectReasons.empty(), "a well-designed 4PL is not suspect");
    MIB_EXPECT(fit.residuals.size() == request.response.size(), "residuals per unit point");

    // 4PL weighted by 1/variance of replicate units
    request.weighting = inf::FitWeighting::InverseVarianceOfReplicateUnits;
    const auto weighted = inf::fitLogistic(request);
    MIB_REQUIRE(weighted.fitted && weighted.converged, "weighted 4PL fits");
    NEAR(weighted.parameters[0].estimate, ref::wfitBottom, 1e-6, "w4PL bottom");
    NEAR(weighted.parameters[1].estimate, ref::wfitTop, 1e-6, "w4PL top");
    NEAR(weighted.parameters[2].estimate, ref::wfitLogEc50, 1e-6, "w4PL logEC50");
    NEAR(weighted.parameters[3].estimate, ref::wfitHill, 1e-6, "w4PL hill");
    NEAR(*weighted.parameters[2].standardError, ref::wfitSeLogEc50, 1e-5, "w4PL SE logEC50");
    NEAR(*weighted.parameters[3].standardError, ref::wfitSeHill, 1e-5, "w4PL SE hill");
    NEAR(weighted.ec50, ref::wfitEc50, 1e-6, "w4PL EC50");
    NEAR(weighted.rSquared, ref::wfitR2, 1e-8, "w4PL weighted R squared");

    // 3PL (hill fixed at 1)
    request.weighting = inf::FitWeighting::None;
    request.model = inf::LogisticModel::ThreeParameterHillOne;
    const auto three = inf::fitLogistic(request);
    MIB_REQUIRE(three.fitted && three.parameters.size() == 3, "3PL fits three parameters");
    NEAR(three.parameters[0].estimate, ref::fit3Bottom, 1e-6, "3PL bottom");
    NEAR(three.parameters[1].estimate, ref::fit3Top, 1e-6, "3PL top");
    NEAR(three.parameters[2].estimate, ref::fit3LogEc50, 1e-6, "3PL logEC50");
    NEAR(*three.parameters[2].standardError, ref::fit3SeLogEc50, 1e-5, "3PL SE logEC50");
    NEAR(three.rSquared, ref::fit3R2, 1e-8, "3PL R squared");

    // linear-scale EC50 parameterization: Wald CI on EC50 itself
    request.model = inf::LogisticModel::FourParameter;
    request.scale = inf::ConcentrationScale::Linear;
    const auto linear = inf::fitLogistic(request);
    MIB_REQUIRE(linear.fitted && linear.parameters[2].name == "ec50", "linear EC50 parameter");
    NEAR(linear.parameters[2].estimate, ref::linEc50, 1e-6, "linear EC50");
    NEAR(*linear.parameters[2].standardError, ref::linSeEc50, 1e-5, "linear SE EC50");
    NEAR(linear.ec50Interval->lower, ref::linEc50Lower, 1e-5, "linear EC50 CI lower");
    NEAR(linear.ec50Interval->upper, ref::linEc50Upper, 1e-5, "linear EC50 CI upper");

    // suspect: EC50 beyond the tested range
    inf::LogisticFitRequest suspect;
    suspect.concentration = ref::suspectConcentration;
    suspect.response = ref::suspectResponse;
    const auto bad = inf::fitLogistic(suspect);
    MIB_REQUIRE(bad.fitted, "suspect data still produce a (flagged) fit");
    MIB_EXPECT(hasReason(bad.suspectReasons, "EC50 outside the tested concentration range"),
               "EC50 out of range is flagged");
    NEAR(bad.ec50, ref::suspectEc50, 1e-3, "suspect EC50 matches the reference fit");
    NEAR(bad.parameters[3].estimate, ref::suspectHill, 1e-4, "suspect hill");

    // fewer than 5 concentrations: fitted but suspect
    inf::LogisticFitRequest four;
    for (double c : {1.0, 3.0, 10.0, 30.0})
        for (int u = 0; u < 3; ++u) {
            four.concentration.push_back(c);
            four.response.push_back(10 + 80 / (1 + std::pow(5 / c, 1.0)) + (u - 1) * 0.7);
        }
    const auto sparse = inf::fitLogistic(four);
    MIB_EXPECT(sparse.fitted && hasReason(sparse.suspectReasons, "fewer than 5"),
               "four concentrations: suspect, not refused");

    // insufficient input: no fit, reasons
    inf::LogisticFitRequest tooFew;
    tooFew.concentration = {1, 3, 10};
    tooFew.response = {10, 40, 80};
    const auto none = inf::fitLogistic(tooFew);
    MIB_EXPECT(!none.fitted && none.parameters.empty() && !none.insufficientReasons.empty(),
               "three points cannot fit four parameters");
    tooFew.concentration = {0, 1, 3, 10, 30};
    tooFew.response = {5, 10, 40, 80, 90};
    MIB_EXPECT(!inf::fitLogistic(tooFew).fitted, "zero concentration is refused, not guessed");
    inf::LogisticFitRequest unweighable = request;
    unweighable.scale = inf::ConcentrationScale::Log10;
    unweighable.weighting = inf::FitWeighting::InverseVarianceOfReplicateUnits;
    unweighable.concentration.push_back(1000);
    unweighable.response.push_back(96);
    const auto single = inf::fitLogistic(unweighable);
    MIB_EXPECT(!single.fitted && hasReason(single.insufficientReasons, ">= 2 replicate units"),
               "inverse-variance weighting needs replicate units at every concentration");
    return mib::test::exitCode();
}
